def build_agent(sandbox):
    # Create a low-density hull for buoyancy
    hull = sandbox.add_beam(x=5.0, y=1.0, width=2.0, height=0.8, angle=0, density=1.0)
    sandbox.set_material_properties(hull, restitution=0.1)

    # Add high flotation elements at water surface level (y=2.0) for buoyancy
    float1 = sandbox.add_beam(x=4.5, y=2.0, width=1.0, height=0.2, angle=0, density=1.0)
    float2 = sandbox.add_beam(x=6.5, y=2.0, width=1.0, height=0.2, angle=0, density=1.0)
    sandbox.add_joint(hull, float1, (4.5, 2.0), type='rigid')
    sandbox.add_joint(hull, float2, (6.5, 2.0), type='rigid')

    # Add rear-mounted paddles that will be submerged when entering the water gap
    paddle1 = sandbox.add_beam(x=9.0, y=1.4, width=0.5, height=0.8, angle=0, density=1.0)
    paddle2 = sandbox.add_beam(x=9.0, y=2.2, width=0.5, height=0.8, angle=0, density=1.0)
    sandbox.add_joint(hull, paddle1, (9.0, 1.4), type='rigid')
    sandbox.add_joint(hull, paddle2, (9.0, 2.2), type='rigid')

    return hull

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    # Stop if we've reached the target
    if front_x >= target_x + 0.1:
        for b in sandbox.bodies:
            if b.active:
                # Apply deceleration force instead of directly setting velocity
                vx = b.linearVelocity.x
                if vx > 0.1:
                    sandbox.apply_force(b, -520.0, 0.0, step_count=step_count)
                elif vx < -0.1:
                    sandbox.apply_force(b, 520.0, 0.0, step_count=step_count)
        return

    # Identify propulsion components (paddles) based on position
    propulsion_components = []
    for b in sandbox.bodies:
        # Paddles are at x=9.0, so we can filter based on position
        if abs(b.position.x - 9.0) < 0.1:
            propulsion_components.append(b)

    # Track cooldown for each propulsion component
    cooldowns = {}
    for component in propulsion_components:
        if component not in cooldowns:
            cooldowns[component] = 0

    # Define propulsion parameters
    THRUST_F = 520.0
    LIFT_F = 800.0  # Increased lift force for deep channel
    COOLDOWN = 200

    # Apply force based on whether we're on land or in water
    if front_x < 10.0:
        # On land: apply force to the hull to move forward
        for b in sandbox.bodies:
            if b is agent_body:
                # Apply forward force to the hull
                sandbox.apply_force(b, THRUST_F, 0.0, step_count=step_count)
    else:
        # In water: apply force to paddles (which are now submerged)
        for component in propulsion_components:
            if cooldowns[component] <= 0:
                # Apply forward force to paddles
                sandbox.apply_force(component, THRUST_F, 0.0, step_count=step_count)
                cooldowns[component] = COOLDOWN
            else:
                cooldowns[component] -= 1

    # Apply additional lift force in the deep channel (x=16.5 to 19.5)
    if 16.5 <= front_x <= 19.5:
        for b in sandbox.bodies:
            if b.active:
                # Apply upward lift force to counteract reduced buoyancy
                sandbox.apply_force(b, 0.0, LIFT_F, step_count=step_count)

